define(["jquery"],function($){"use strict";function getString(key,fallback){var component="proctoringpolicy_password";try{if(window.M&&window.M.util&&window.M.util.get_string){return window.M.util.get_string(key,component)}}catch(e){}return fallback||""}function postAjax(url,data){return $.ajax({url:url,method:"POST",dataType:"json",data:data})}function init(ctx,cfg){if(!cfg){return}var cmid=Number(ctx.cmid||0);var attemptid=Number(ctx.attemptid||0);var $container=$('[data-kppass="container"]');if($container.length===0){return}var $status=$container.find('[data-kppass="status"]');var $inputPassword=$container.find('[data-kppass="password"]');var $btnSubmit=$container.find('[data-kppass="submit"]');var polling=null;if(ctx.api&&typeof ctx.api.registerRequirement==="function"){ctx.api.registerRequirement("password",{label:cfg.requirementlabel||"Teacher approval or exam password",satisfied:false})}function setRequirementSatisfied(satisfied){if(ctx.api&&typeof ctx.api.updateRequirement==="function"){ctx.api.updateRequirement("password",{satisfied:!!satisfied})}}function setStatus(text){$status.text(text||"")}function handleStatusResponse(resp){if(!resp||!resp.status){return}if(resp.status==="pending"){setRequirementSatisfied(false);setStatus(getString("js_status_pending","Request sent. Waiting approval."))}else if(resp.status==="approved"){setRequirementSatisfied(true);setStatus(getString("js_status_approved","Approved. You can start the exam."));window.dispatchEvent(new CustomEvent("kopere_proctoring_password_authorized",{detail:{cmid:cmid,attemptid:attemptid}}));if(polling){window.clearInterval(polling);polling=null}}else if(resp.status==="blocked"){setRequirementSatisfied(false);setStatus(getString("js_status_blocked","You are temporarily blocked."));if(polling){window.clearInterval(polling);polling=null}}}function checkStatus(){return postAjax(M.cfg.wwwroot+"/local/kopere_proctoring/policy/password/ajax.php",{action:"check",cmid:cmid,attemptid:attemptid}).done(function(response){handleStatusResponse(response)})}function startPolling(){if(polling){return}checkStatus();polling=window.setInterval(checkStatus,3e3)}startPolling();$btnSubmit.on("click",function(){var code=($inputPassword.val()||"").replace(/\D/g,"");if(code.length!==8){setRequirementSatisfied(false);setStatus(getString("js_wrong_password","Invalid password."));return}postAjax(M.cfg.wwwroot+"/local/kopere_proctoring/policy/password/ajax.php",{action:"submitcode",cmid:cmid,attemptid:attemptid,code:code}).done(function(resp){if(!resp){return}if(resp.error==="blocked"){setRequirementSatisfied(false);setStatus(getString("js_toomany_errors","Too many wrong attempts. Please wait 10 minutes."));return}if(resp.error==="wrong"){setRequirementSatisfied(false);setStatus(getString("js_wrong_password","Invalid password."));return}if(resp.status==="approved"){handleStatusResponse(resp)}})})}return{init:init}});